create function public.has_permission(p_code text) returns boolean
language sql stable security invoker set search_path = '' as $$
 select exists(select 1 from public.profiles p join public.role_permissions rp on rp.role_id=p.role_id
 where p.id=(select auth.uid()) and p.active and rp.permission_code=p_code and rp.mode='allowed');
$$;
revoke all on function public.has_permission(text) from public,anon,authenticated;
grant execute on function public.has_permission(text) to authenticated;
create table public.categories(id uuid primary key default gen_random_uuid(), name text not null unique check(length(trim(name))>0),active boolean not null default true);
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id),name text not null check(length(trim(name))>0),sku text unique,barcode text unique,unit text not null default 'unidade',price_cents bigint not null check(price_cents between 0 and 1000000000),minimum_stock numeric(14,3) not null default 0 check(minimum_stock>=0),service_eligible boolean not null default true,active boolean not null default true,created_at timestamptz not null default now());
create table public.product_costs(product_id uuid primary key references public.products(id),cost_cents bigint not null check(cost_cents>=0));
create table public.packaging_units(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),name text not null,base_quantity numeric(14,3) not null check(base_quantity>0),unique(product_id,name));
create table public.inventory_balances(product_id uuid primary key references public.products(id),physical numeric(14,3) not null default 0,reserved numeric(14,3) not null default 0,check(physical>=reserved and reserved>=0));
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),actor_id uuid not null references public.profiles(id),kind text not null check(kind in ('receipt','withdrawal','adjustment','sale','return','loss')),quantity_delta numeric(14,3) not null check(quantity_delta<>0),previous_balance numeric(14,3) not null,new_balance numeric(14,3) not null,reason text not null check(length(trim(reason))>0),request_id uuid not null unique,created_at timestamptz not null default now(),check(previous_balance+quantity_delta=new_balance and new_balance>=0));
create table public.customers(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name))>0),phone text,email text,notes text,created_by uuid not null default auth.uid() references public.profiles(id),created_at timestamptz not null default now());
create table public.customer_addresses(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id),postal_code text,street text not null,number text,neighborhood text,complement text,reference text,city text,state text);
create table public.tables(id uuid primary key default gen_random_uuid(),name text not null unique,capacity integer check(capacity>0),area text,active boolean not null default true);
create table public.table_sessions(id uuid primary key default gen_random_uuid(),table_id uuid not null references public.tables(id),opened_by uuid not null references public.profiles(id),customer_name text,guest_count integer not null default 1 check(guest_count>0),opened_at timestamptz not null default now(),closed_at timestamptz,check(closed_at is null or closed_at>=opened_at));
create unique index one_open_table_session on public.table_sessions(table_id) where closed_at is null;
create table public.cash_registers(id uuid primary key default gen_random_uuid(),name text not null unique,active boolean not null default true);
create table public.cash_sessions(id uuid primary key default gen_random_uuid(),register_id uuid not null references public.cash_registers(id),operator_id uuid not null references public.profiles(id),opening_cents bigint not null check(opening_cents>=0),opened_at timestamptz not null default now(),closed_at timestamptz,counted_cents bigint check(counted_cents>=0),expected_cents bigint,check((closed_at is null and counted_cents is null and expected_cents is null) or (closed_at>=opened_at and counted_cents is not null and expected_cents is not null)));
create unique index one_open_cash_register on public.cash_sessions(register_id) where closed_at is null;
create table public.orders(id uuid primary key default gen_random_uuid(),number bigint generated always as identity unique,channel text not null check(channel in ('mesa','balcao','retirada','delivery')),status text not null default 'draft' check(status in ('draft','confirmed','fulfilled','paid','cancelled')),table_session_id uuid references public.table_sessions(id),customer_id uuid references public.customers(id),customer_name text,created_by uuid not null references public.profiles(id),service_accepted boolean not null default true,delivery_fee_cents bigint not null default 0 check(delivery_fee_cents>=0),created_at timestamptz not null default now(),check((channel='mesa')=(table_session_id is not null)),check(channel='delivery' or delivery_fee_cents=0));
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),product_id uuid not null references public.products(id),product_name text not null,quantity integer not null check(quantity>0),unit_price_cents bigint not null check(unit_price_cents>=0),service_eligible boolean not null,state text not null default 'draft' check(state in ('draft','reserved','fulfilled','cancelled')),notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),cash_session_id uuid not null references public.cash_sessions(id),actor_id uuid not null references public.profiles(id),method text not null check(method in ('cash','pix','debit','credit')),amount_cents bigint not null check(amount_cents>0),received_cents bigint not null,change_cents bigint not null default 0 check(change_cents>=0),request_id uuid not null unique,created_at timestamptz not null default now(),check(received_cents=amount_cents+change_cents),check(method='cash' or change_cents=0));
create table public.cash_movements(id uuid primary key default gen_random_uuid(),cash_session_id uuid not null references public.cash_sessions(id),actor_id uuid not null references public.profiles(id),kind text not null check(kind in ('addition','withdrawal','refund')),amount_cents bigint not null check(amount_cents>0),reason text not null check(length(trim(reason))>0),request_id uuid not null unique,created_at timestamptz not null default now());
create index products_category_idx on public.products(category_id);
create index packaging_product_idx on public.packaging_units(product_id);
create index inventory_movements_product_idx on public.inventory_movements(product_id,created_at desc);
create index addresses_customer_idx on public.customer_addresses(customer_id);
create index orders_table_idx on public.orders(table_session_id);
create index orders_customer_idx on public.orders(customer_id);
create index order_items_order_idx on public.order_items(order_id);
create index payments_order_idx on public.payments(order_id);
create index payments_cash_idx on public.payments(cash_session_id);
create index cash_movements_session_idx on public.cash_movements(cash_session_id);
alter table public.categories enable row level security;
revoke all on public.categories from public,anon,authenticated;
grant select on public.categories to authenticated;
create policy categories_read on public.categories for select to authenticated using ((select public.has_permission('products.view')));
