create policy cash_sessions_read on public.cash_sessions for select to authenticated using ((select public.has_permission('cash.view_all')) or ((select public.has_permission('cash.view_own')) and operator_id=(select auth.uid())));
create policy payments_read on public.payments for select to authenticated using ((select public.has_permission('cash.view_all')) or exists(select 1 from public.cash_sessions s where s.id=payments.cash_session_id));
create policy cash_movements_read on public.cash_movements for select to authenticated using ((select public.has_permission('cash.view_all')) or exists(select 1 from public.cash_sessions s where s.id=cash_movements.cash_session_id));
grant select on public.audit_events to authenticated;
